function() {
  // Haalt het adres van de bezoeker uit de URL voordat die naar GA4 gaat.
  // Op /subsidiecheck staat de volledige invoer in de querystring
  // (?pc=9711AB&hn=5&tv=a of ?str=…&pl=… bij een handmatig adres). Dat is
  // een persoonsgegeven en hoort niet in analytics.
  //
  // De overige parameters blijven staan, zodat utm-attributie blijft werken.
  var ADRES_PARAMS = ['pc', 'hn', 'tv', 'str', 'pl'];
  try {
    var url = new URL(String(window.location.href));
    for (var i = 0; i < ADRES_PARAMS.length; i++) {
      url.searchParams.delete(ADRES_PARAMS[i]);
    }
    return url.toString();
  } catch (e) {
    // Kan de URL niet geparsed worden, dan liever de hele querystring kwijt
    // dan het risico dat er een adres doorheen glipt.
    return String(window.location.href).split('?')[0];
  }
}
